class Solution {
public:
    bool possibleBipartition(int n, vector<vector<int>>& dislikes) {
        vector<vector<int>> adj(n + 1);
        for (auto& d : dislikes) {
            adj[d[0]].push_back(d[1]);
            adj[d[1]].push_back(d[0]);
        }
        vector<int> color(n + 1, 0);
        for (int s = 1; s <= n; s++) {
            if (color[s]) continue;
            queue<int> q;
            q.push(s);
            color[s] = 1;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (int v : adj[u]) {
                    if (color[v] == color[u]) return false;
                    if (!color[v]) {
                        color[v] = 3 - color[u];
                        q.push(v);
                    }
                }
            }
        }
        return true;
    }
};
